const cleanFilter=()=>({status:'all',sort:'urgency',direction:'asc',ranks:'SABCD',estimateMode:'any',min:'',max:'',deadlineMode:'any',deadlineFrom:'',deadlineTo:'',createdFrom:'',createdTo:'',type:'all'});
const pageKey=()=>['week','month'].includes(state.page)?'calendar':state.page;
Object.assign(state,{prefs:{tasks:cleanFilter(),progress:cleanFilter(),history:{...cleanFilter(),status:'done'},calendar:cleanFilter()},drafts:{},detailOnly:false,calendarPage:'week',toasts:[],pendingToasts:[],toastHover:false,reminderEdit:null,reminderDraft:null,settings:{monitor:'auto',secondary:'Дополнительный монитор',autorun:true,summary:true,summaryMinutes:180,summaryLimit:3,snooze:30,sound:true},reminders:[
 {id:101,title:'Размяться и отдохнуть от экрана',kind:'signal',schedule:'hourly',minute:0,time:'15:00',first:'2026-11-18',days:[1],interval:14,unit:'days',repeat:30,enabled:true,due:null,history:[]},
 {id:102,title:'Сменить постельное бельё',kind:'confirmed',schedule:'after',minute:0,time:'15:00',first:'2026-11-18',days:[1],interval:14,unit:'days',repeat:60,enabled:true,due:'2026-11-18T15:00:00',history:[{due:'2026-11-04T15:00:00',completed:'2026-11-04T16:15:00'}]}
]});
state.tasks.forEach(t=>{t.doneAt=t.done?'2026-11-17T19:00:00':null;t.personal=t.id===1?{enabled:true,first:'2026-11-18T15:00:00',repeat:180}:null;});
let holdOrder=[],toastSequence=0,lastSound=-Infinity,filterDraft=null,confirmAction=null,settingsSaved='',formatHistory=[],hostRevision='';
const storeKey='notifs-approved-prototype-v1';
const filterDialog=document.createElement('dialog');filterDialog.className='nx-dialog nx-filter-dialog';filterDialog.setAttribute('aria-labelledby','nx-filter-title');app.append(filterDialog);
checkin.className='nx-toast-stack';checkin.setAttribute('aria-label','Уведомления');
const baseCard=card,baseDetails=details,baseEditor=editorView,baseMonth=monthView,baseWeek=weekStrip,basePaintRange=paintRange;
const clone=v=>JSON.parse(JSON.stringify(v));
const currentFilter=()=>state.prefs[pageKey()]||state.prefs.tasks;
const blankTask=()=>({title:'',description:'',date:'',time:'',estimate:'',rank:'B',personalEnabled:false,personalFirst:'',personalRepeat:180});
const draftKey=()=>state.edit?'task-'+state.edit:'new';
const getReminder=id=>state.reminders.find(r=>r.id===Number(id));
const unsignedDuration=n=>{const m=Math.max(0,Math.round(n));return m?duration(m):'0 мин';};
const filterNames={urgency:'По срочности',rank:'По рангу',estimate:'По полной оценке',deadline:'По дедлайну',created:'По созданию'};
function snapshot(){return {tasks:state.tasks,sessions:state.sessions,drafts:state.drafts,prefs:state.prefs,settings:state.settings,reminders:state.reminders,removedTask,nextTaskId,now:state.now,calendar:{week:state.week,period:state.period,range:state.range,month:state.month,year:state.year,page:state.calendarPage}};}
function remember(){const data=snapshot(),serialized=JSON.stringify(data);try{localStorage.setItem(storeKey,serialized);}catch{}hostRevision='notifs-'+Date.now()+'-'+Math.random();if(serialized.length<14000)globalThis.openai?.setWidgetState?.({modelContent:null,privateContent:{notifs:data,revision:hostRevision}})?.catch(()=>{});}
function loadSnapshot(data){if(!data?.tasks||!data?.prefs)return;for(const name of ['tasks','sessions','drafts','prefs','settings','reminders'])if(data[name])state[name]=clone(data[name]);removedTask=data.removedTask||null;nextTaskId=data.nextTaskId||Math.max(...state.tasks.map(t=>t.id))+1;state.offset=(data.now||initialNow)-initialNow;state.now=data.now||initialNow;if(data.calendar){Object.assign(state,data.calendar);state.calendarPage=data.calendar.page||'week';state.page='tasks';}pauseEverySession();state.toasts=[];state.pendingToasts=[];}
try{const saved=JSON.parse(localStorage.getItem(storeKey)||'null');if(saved)loadSnapshot(saved);}catch{}
const savedInline=globalThis.openai?.widgetState?.privateContent||globalThis.openai?.widgetState;
if(savedInline?.notifs){hostRevision=savedInline.revision||'';loadSnapshot(savedInline.notifs);}
if(!state.tasks.some(t=>t.id===state.selected))state.selected=state.tasks[0]?.id??null;
function positionModal(el){el.showModal();const box=app.getBoundingClientRect();el.style.top=Math.max(20,box.top+(Math.min(box.height,1000)-el.getBoundingClientRect().height)/2)+'px';refreshIcons();}
function pauseSession(id){const s=state.sessions[id];if(!s||s.pausedAt)return;s.activeMs=activeElapsed(s);s.activeSince=null;s.pausedAt=state.now;s.remainingMs=s.due===null?null:Math.max(0,s.due-state.now);s.due=null;}
function pauseEverySession(except=null){for(const id of Object.keys(state.sessions))if(Number(id)!==Number(except))pauseSession(id);}
function resumeSession(t){pauseEverySession(t.id);const s=state.sessions[t.id];if(!s)return;s.activeSince=state.now;s.pausedAt=null;s.due=s.remainingMs===null||s.notified?null:state.now+s.remainingMs;}
function removeToasts(test){state.toasts=state.toasts.filter(n=>!test(n));state.pendingToasts=state.pendingToasts.filter(n=>!test(n));}
function sound(){if(!state.settings.sound||state.now-lastSound<1000)return;lastSound=state.now;try{const Audio=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Audio)return;const context=new Audio(),osc=context.createOscillator(),gain=context.createGain();osc.type='sine';osc.frequency.value=660;gain.gain.setValueAtTime(.035,context.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,context.currentTime+.13);osc.connect(gain);gain.connect(context.destination);osc.start();osc.stop(context.currentTime+.15);osc.onended=()=>context.close();}catch{}}
function notify(kind,taskId=null,reminderId=null){const data={id:++toastSequence,kind,taskId,reminderId,time:state.now};if(kind==='summary')data.taskIds=sortItems(state.tasks.filter(t=>!t.done&&(!t.snooze||stamp(t.snooze)<=state.now)),{...cleanFilter()}).slice(0,state.settings.summaryLimit).map(t=>t.id);if(kind==='summary'&&!data.taskIds.length)return;sound();if(state.toastHover)state.pendingToasts=[...state.pendingToasts,data].slice(-2);else state.toasts=[...state.toasts,data].slice(-2);paintNotification();}
function filterCount(f){return Number(f.ranks!=='SABCD')+Number(f.estimateMode!=='any')+Number(f.deadlineMode!=='any')+Number(!!(f.createdFrom||f.createdTo))+Number(f.type!=='all');}
function matches(t,f){if(t.reminderId)return f.type!=='tasks'&&f.ranks==='SABCD'&&f.estimateMode==='any'&&f.deadlineMode==='any'&&!f.createdFrom&&!f.createdTo;if(f.type==='reminders')return false;if(!f.ranks.includes(t.rank))return false;if(f.estimateMode==='none'&&t.estimate)return false;if(f.estimateMode==='range'&&(!t.estimate||(f.min!==''&&t.estimate<Number(f.min))||(f.max!==''&&t.estimate>Number(f.max))))return false;if(f.deadlineMode==='none'&&t.deadline)return false;if(f.deadlineMode==='range'&&(!t.deadline||(f.deadlineFrom&&day(t.deadline)<f.deadlineFrom)||(f.deadlineTo&&day(t.deadline)>f.deadlineTo)))return false;return (!f.createdFrom||day(t.created)>=f.createdFrom)&&(!f.createdTo||day(t.created)<=f.createdTo);}
function urgency(a,b){const da=a.deadline?stamp(a.deadline):null,db=b.deadline?stamp(b.deadline):null;if(da===null||db===null){if(da!==db)return da===null?1:-1;return stamp(a.created)-stamp(b.created)||a.id-b.id;}const oa=da<state.now,ob=db<state.now;if(oa!==ob)return oa?-1:1;return (oa?da-db:(da-a.estimate*60000)-(db-b.estimate*60000))||da-db||'SABCD'.indexOf(a.rank)-'SABCD'.indexOf(b.rank)||a.id-b.id;}
function sortItems(items,f=currentFilter()){const ordered=[...items].sort((a,b)=>{if(a.done!==b.done)return a.done?1:-1;if(a.reminderId||b.reminderId){if(a.reminderId&&b.reminderId)return a.id.localeCompare(b.id);return a.reminderId?1:-1;}if(f.sort==='urgency'){if(a.done)return stamp(b.doneAt||b.created)-stamp(a.doneAt||a.created)||a.id-b.id;return urgency(a,b);}const value=t=>f.sort==='rank'?'SABCD'.indexOf(t.rank):f.sort==='estimate'?(t.estimate||null):f.sort==='deadline'?(t.deadline?stamp(t.deadline):null):stamp(t.created);const av=value(a),bv=value(b);if(av===null||bv===null)return av===bv?a.id-b.id:av===null?1:-1;return (av-bv)*(f.direction==='desc'?-1:1)||a.id-b.id;});for(const id of state.sticky){const at=ordered.findIndex(t=>t.id===id),was=holdOrder.indexOf(id);if(at>=0&&was>=0){const item=ordered.splice(at,1)[0];ordered.splice(Math.min(was,ordered.length),0,item);}}return ordered;}
filterItems=function(items){const f=currentFilter();state.filter=f.status;return sortItems(items.filter(t=>matches(t,f)&&(f.status==='all'||state.sticky.has(t.id)||(f.status==='done'?t.done:!t.done))),f);};
reasons=function(t,p){if(t.reminderId)return t.calendarReasons||[];const has=v=>v&&day(v)>=p.from&&day(v)<=p.to,result=[];if(has(t.created))result.push('Создана');if(has(t.lastStart||state.sessions[t.id]?.start))result.push('Начал делать');if(has(t.deadline))result.push('Дедлайн');const end=estimated(t);if(end&&day(t.created)<=p.to&&day(end)>=p.from)result.push('Расчётный промежуток');const s=state.sessions[t.id];if(s?.due&&has(s.due))result.push('Вопрос о результате');return result;};
function reminderDates(r,p){const list=[];if(r.kind!=='confirmed')return list;if(r.due&&day(r.due)>=p.from&&day(r.due)<=p.to)list.push({date:day(r.due),reason:'Текущее дело',planned:false});for(const h of r.history){if(day(h.completed)>=p.from&&day(h.completed)<=p.to)list.push({date:day(h.completed),reason:'Выполнено',done:true});if(day(h.due)!==day(h.completed)&&day(h.due)>=p.from&&day(h.due)<=p.to)list.push({date:day(h.due),reason:'Исходный срок',done:true});}if(r.enabled&&r.schedule==='weekly'){for(let d=p.from;d<=p.to;d=addDay(d,1)){if(d>=r.first&&stamp(d)>state.now&&r.days.includes(new Date(stamp(d)).getUTCDay()))list.push({date:d,reason:'По расписанию',planned:true});}}return list;}
periodTasks=function(p){const ordinary=state.tasks.filter(t=>reasons(t,p).length);const repeated=state.reminders.flatMap(r=>{const dates=reminderDates(r,p);return dates.length?[{id:'r'+r.id,reminderId:r.id,title:r.title,done:dates.every(d=>d.done),planned:dates.every(d=>d.planned),calendarReasons:[...new Set(dates.map(d=>d.reason))]}]:[];});return [...ordinary,...repeated];};
card=function(t,options={}){if(!t.reminderId)return baseCard(t,options);return `<article class="nx-task ${t.done?'nx-completed':''}"><button type="button" class="nx-cardhit" data-action="open-reminder" data-id="${t.reminderId}" aria-label="Открыть напоминание: ${esc(t.title)}"><span class="nx-tasktitle">${esc(t.title)}</span><span class="nx-meta">${icon('repeat-2')}Повторяющееся дело</span><span class="nx-reasons">${(t.calendarReasons||[]).map(x=>`<span class="nx-reason">${esc(x)}</span>`).join('')}</span></button></article>`;};
details=function(t){if(t?.reminderId){const r=getReminder(t.reminderId);return `<section class="nx-detail"><p class="nx-overline">ПОВТОРЯЮЩЕЕСЯ ДЕЛО</p><h2>${esc(r.title)}</h2><p class="nx-subtitle">${scheduleLabel(r)}</p><p class="nx-small nx-muted" style="margin-top:18px">${t.planned?'Плановая отметка. Выполнение станет доступно, когда наступит срок.':t.done?'Выполнение сохранено в календаре.':'Текущее дело доступно в разделе «Напоминания».'}</p><div class="nx-actions"><button class="nx-button nx-primary" data-action="open-reminder" data-id="${r.id}">Открыть напоминание</button></div></section>`;}let html=baseDetails(t);if(!t)return html;if(t.deadline){const slack=Math.round((stamp(t.deadline)-state.now)/60000)-t.estimate;html=html.replace(/(<dt>Запас времени<\/dt><dd>)[\s\S]*?(<\/dd>)/,`$1${slack<0?'−':''}${unsignedDuration(Math.abs(slack))}$2`);}return html;};
filterBar=function(items){const f=currentFilter(),options=[['all','Все',items.length],['open','Не сделаны',items.filter(t=>!t.done).length],['done','Сделаны',items.filter(t=>t.done).length]];return `<div class="nx-filters" role="group" aria-label="Состояние задач">${options.map(([k,label,n])=>`<button class="nx-filter" data-action="filter" data-filter="${k}" aria-pressed="${f.status===k}">${label} ${n}</button>`).join('')}</div>`;};
function tools(){const f=currentFilter(),count=filterCount(f);return `<div class="nx-listtools"><span class="nx-sectionlabel">${filterNames[f.sort]}${f.sort!=='urgency'?(f.direction==='asc'?' ↑':' ↓'):''}</span><button class="nx-button" data-action="open-filters">${icon('sliders-horizontal')}Фильтры и сортировка${count?' · '+count:''}</button></div>`;}
listView=function(){const base=baseItems(),items=filterItems(base);let t=items.find(x=>x.id===state.selected);if(!t){t=items[0];state.selected=t?.id??null;}const labels={progress:['В процессе','Начатые дела и сохранённые паузы.'],history:['История','Завершённые дела остаются рядом.'],week:['Календарь','Неделя рядом с задачами. Полный месяц — в один клик.'],tasks:['Мои задачи','Список слева. Внимание — на одном деле.']},[title,subtitle]=labels[state.page]||labels.tasks;return header(title,subtitle)+(state.page==='week'?weekStrip():'')+tools()+`<div class="nx-split"><section><div class="nx-sectionlabel"><span>${state.page==='progress'?'НАЧАТЫЕ ЗАДАЧИ':'ЗАДАЧИ'}</span><span>${items.length}</span></div><div class="nx-queue">${items.map(x=>card(x,{period:state.page==='week'?state.period:null})).join('')||`<div class="nx-empty"><h2>${state.page==='progress'?'Пока ничего не начато':'Здесь пока пусто'}</h2><p>Измените фильтры или добавьте задачу.</p><button class="nx-button" data-action="open-filters">Проверить фильтры</button></div>`}</div>${filterBar(base)}</section><div><button class="nx-button nx-back-list" data-action="back-list">${icon('arrow-left')}К списку</button>${details(t)}</div></div>`;};
weekStrip=function(){return baseWeek().replace('<div class="nx-weekcontrols">','<div class="nx-weekcontrols"><button class="nx-button" data-action="today">Сегодня</button>');};
monthView=function(){return baseMonth().replace('<div class="nx-monthhead">',tools()+'<div class="nx-monthhead">').replaceAll('periodTasks({from:d,to:d})','periodTasks({from:d,to:d})');};
monthGrid=function(){const begin=startWeek(key(Date.UTC(state.year,state.month,1,12))),days=Array.from({length:42},(_,i)=>addDay(begin,i));return `<div class="nx-weeknames">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(n=>'<span>'+n+'</span>').join('')}</div><div class="nx-monthgrid" role="group" aria-label="Дни месяца, доступно выделение периода">${days.map(d=>{const items=periodTasks({from:d,to:d});return `<button type="button" class="nx-day ${Number(d.slice(5,7))-1!==state.month?'nx-outside':''} ${d===day(state.now)?'nx-today':''} ${d>=state.range.from&&d<=state.range.to?'nx-inrange':''}" data-action="month-day" data-date="${d}" aria-pressed="${d>=state.range.from&&d<=state.range.to}" aria-label="${dateLabel(d)}. Задач: ${items.length}. ${esc(items.map(t=>t.title).join('; '))}"><span class="nx-daynumber">${Number(d.slice(-2))}</span>${items.slice(0,3).map(t=>`<span class="nx-daytask ${t.done?'nx-done':''}" data-tooltip="${esc(t.title)}">${t.reminderId?'<span class="nx-repeat-mark">'+icon('repeat-2')+'</span>':rank(t)}<span class="nx-daytasktitle">${esc(t.title)}</span></span>`).join('')}${items.length>3?'<span class="nx-more">Ещё '+(items.length-3)+'</span>':''}</button>`;}).join('')}</div>`;};
// Base month rendering receives filtered calendar data through this dedicated drawing function.
const unfilteredPeriodTasks=periodTasks;
periodTasks=function(p){const items=unfilteredPeriodTasks(p);return state.page==='month'?filterItems(items):items;};
function option(value,text,selected){return `<option value="${value}" ${String(value)===String(selected)?'selected':''}>${text}</option>`;}
function field(label,name,value,type='text',extra=''){return `<label class="nx-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,options,value){return `<label class="nx-field">${label}<select name="${name}">${options.map(([v,t])=>option(v,t,value)).join('')}</select></label>`;}
function checkbox(label,name,checked){return `<label class="nx-checkrow"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;}
function filterForm(){const f=filterDraft;return `<div class="nx-paneltitle"><div><p class="nx-overline">НАСТРОЙКИ СПИСКА</p><h2 id="nx-filter-title">Фильтры и сортировка</h2></div><button class="nx-iconbutton" data-action="close-filters" aria-label="Закрыть фильтры">${icon('x')}</button></div><form><div class="nx-formrow">${select('Порядок','sort',Object.entries(filterNames),f.sort)}${select('Направление','direction',[['asc','По возрастанию · S → D'],['desc','По убыванию · D → S']],f.direction)}</div><fieldset><legend>Какие задачи показывать</legend>${pageKey()==='calendar'?select('Тип элементов','type',[['all','Все'],['tasks','Обычные задачи'],['reminders','Повторяющиеся дела']],f.type):''}<div class="nx-small nx-muted" style="margin:0 0 8px">Ранг · можно выбрать несколько</div><div class="nx-rankchoices">${[...'SABCD'].map(r=>`<label class="nx-checkrow"><input name="rank-${r}" type="checkbox" ${f.ranks.includes(r)?'checked':''}>${rank({rank:r})}</label>`).join('')}</div>${select('Полная оценка','estimateMode',[['any','Любая'],['range','В диапазоне'],['none','Без оценки']],f.estimateMode)}<div class="nx-formrow">${field('От, минут','min',f.min,'number','min="1"')}${field('До, минут','max',f.max,'number','min="1"')}</div>${select('Дедлайн','deadlineMode',[['any','Любой'],['range','В диапазоне'],['none','Без дедлайна']],f.deadlineMode)}<div class="nx-formrow">${field('Дедлайн с','deadlineFrom',f.deadlineFrom,'date')}${field('По','deadlineTo',f.deadlineTo,'date')}</div><div class="nx-formrow">${field('Создана с','createdFrom',f.createdFrom,'date')}${field('По','createdTo',f.createdTo,'date')}</div>${pageKey()==='calendar'?'<p class="nx-small nx-muted">Ранг, оценка, дедлайн и создание относятся к обычным задачам. При таком отборе повторяющиеся дела скрыты.</p>':''}</fieldset><p class="nx-error" data-filter-error role="alert"></p><div class="nx-actions"><button type="button" class="nx-button" data-action="reset-filters">Сбросить</button><button type="button" class="nx-button nx-primary" data-action="apply-filters">Применить</button></div></form>`;}
function collectFilter(){const f={...filterDraft};for(const name of Object.keys(f)){const el=filterDialog.querySelector(`[name="${name}"]`);if(el)f[name]=el.value;}f.ranks=[...'SABCD'].filter(r=>filterDialog.querySelector(`[name="rank-${r}"]`).checked).join('');return f;}
saveDraft=function(){if(state.page!=='new')return;main.querySelectorAll('[name]').forEach(el=>{if(Object.hasOwn(state.draft,el.name))state.draft[el.name]=el.type==='checkbox'?el.checked:el.value;});state.drafts[draftKey()]={...state.draft};};
function openTaskEditor(t=null){state.edit=t?.id??null;state.page='new';state.preview=false;state.error=false;const p=t?.personal;state.draft=clone(state.drafts[draftKey()]||(t?{title:t.title,description:t.description,date:t.deadline?.slice(0,10)||'',time:t.deadline?.slice(11,16)||'',estimate:t.estimate||'',rank:t.rank,personalEnabled:!!p?.enabled,personalFirst:p?.first?.slice(0,16)||'',personalRepeat:p?.repeat||180}:blankTask()));formatHistory=[];}
editorView=function(){const d=state.draft;let html=baseEditor();html=html.replace('<div class="nx-actions">',`<details class="nx-personal" ${d.personalEnabled?'open':''}><summary>Личные напоминания</summary>${checkbox('Напоминать об этой задаче','personalEnabled',d.personalEnabled)}<div class="nx-formrow">${field('Первое напоминание','personalFirst',d.personalFirst,'datetime-local')}${field('Повторять каждые, минут','personalRepeat',d.personalRepeat,'number','min="1"')}</div><p class="nx-small nx-muted">Продолжаются и во время занятия. Дедлайн не меняют.</p></details><div class="nx-actions">`);html=html.replace('К задачам</button>','К задачам</button><button class="nx-button" data-action="discard-draft">Отбросить изменения</button>');return html;};
saveTask=function(){saveDraft();const d=state.draft;if(!d.title.trim()||(d.estimate!==''&&Number(d.estimate)<=0)||(d.personalEnabled&&(!d.personalFirst||Number(d.personalRepeat)<=0))){state.error=true;state.notice='Проверьте название, положительную оценку и расписание.';render();main.querySelector('[name="title"]')?.focus();return;}const original=getTask(state.edit),oldEstimate=original?.estimate,id=original?.id??nextTaskId++;const data={...(original||{}),id,title:d.title.trim(),description:d.description,rank:d.rank,created:original?.created??new Date(state.now).toISOString().slice(0,19),deadline:d.date?d.date+'T'+(d.time?d.time+':00':'23:59:59.999'):'',estimate:Number(d.estimate)||0,done:original?.done??false,personal:d.personalEnabled?{enabled:true,first:d.personalFirst+':00',repeat:Number(d.personalRepeat)}:null};if(original)Object.assign(original,data);else state.tasks.push(data);if(original&&oldEstimate!==data.estimate&&state.sessions[id]){const s=state.sessions[id],remaining=data.estimate?Math.max(0,data.estimate*60000-activeElapsed(s)):null;s.remainingMs=remaining;s.due=s.pausedAt||remaining===null?null:state.now+remaining;s.notified=false;removeToasts(n=>n.kind==='checkin'&&n.taskId===id);}delete state.drafts[draftKey()];state.page='tasks';state.selected=id;state.edit=null;state.sticky.clear();state.notice='Задача сохранена.';remember();render();updateTime();};
formatSelection=function(marker,toggle=false){const f=main.querySelector('textarea[name="description"]');if(!f)return;let a=f.selectionStart,b=f.selectionEnd;const selected=f.value.slice(a,b);let replacement=marker+selected+marker,selection=a+marker.length;if(toggle&&f.value.slice(Math.max(0,a-marker.length),a)===marker&&f.value.slice(b,b+marker.length)===marker){a-=marker.length;b+=marker.length;replacement=selected;selection=a;}else if(toggle&&selected.startsWith(marker)&&selected.endsWith(marker)&&selected.length>=marker.length*2){replacement=selected.slice(marker.length,-marker.length);selection=a;}f.focus({preventScroll:true});f.setSelectionRange(a,b);const before=f.value;formatHistory.push({value:before,start:a,end:b});if(!document.execCommand('insertText',false,replacement))f.setRangeText(replacement,a,b,'end');f.setSelectionRange(selection,selection+(replacement===selected?selected.length:replacement.startsWith(marker)?selected.length:replacement.length));f.dispatchEvent(new Event('input',{bubbles:true}));};
function scheduleLabel(r){if(r.schedule==='hourly')return 'Простой сигнал · каждый час, в :'+String(r.minute).padStart(2,'0');if(r.schedule==='after')return 'Дело с подтверждением · через '+r.interval+' '+(r.unit==='hours'?'ч':'дн.')+' после выполнения';return (r.kind==='confirmed'?'Дело с подтверждением':'Простой сигнал')+' · '+r.days.map(d=>['вс','пн','вт','ср','чт','пт','сб'][d]).join(', ')+' в '+r.time;}
function reminderList(){return header('Напоминания','Повторяющиеся сигналы и дела — в одном месте.')+`<div class="nx-listtools"><span class="nx-sectionlabel">РАСПИСАНИЯ · ${state.reminders.length}</span><button class="nx-button nx-primary" data-action="new-reminder">${icon('plus')}Новое напоминание</button></div>`+state.reminders.map(r=>`<article class="nx-reminder ${r.enabled?'':'nx-disabled'}"><span class="nx-reminder-icon">${icon(r.kind==='signal'?'bell':'repeat-2')}</span><div class="nx-reminder-copy"><div class="nx-reminder-status">${r.enabled?'ВКЛЮЧЕНО':'ВЫКЛЮЧЕНО'} · ${r.kind==='signal'?'ПРОСТОЙ СИГНАЛ':'С ПОДТВЕРЖДЕНИЕМ'}</div><h3>${esc(r.title)}</h3><p>${scheduleLabel(r)}</p>${r.due?`<p>${stamp(r.due)<=state.now?'Не выполнено с ':'Ближайший срок: '}${dateLabel(r.due)}, ${timeLabel(r.due)}</p>`:''}<div class="nx-actions">${r.kind==='confirmed'&&r.due&&stamp(r.due)<=state.now?`<button class="nx-button nx-primary" data-action="reminder-done" data-id="${r.id}">${icon('check')}Готово</button>`:''}<button class="nx-button" data-action="open-reminder" data-id="${r.id}">${icon('pencil')}Изменить</button><button class="nx-button" data-action="toggle-reminder" data-id="${r.id}" aria-pressed="${r.enabled}">${r.enabled?'Выключить':'Включить'}</button><button class="nx-button nx-delete" data-action="delete-reminder" data-id="${r.id}">${icon('trash-2')}Удалить</button></div>${r.history.length?`<div class="nx-reminder-history"><p><span>Последнее выполнение</span><span>${dateLabel(r.history.at(-1).completed)}</span></p></div>`:''}</div></article>`).join('')||'<div class="nx-empty">Пока нет напоминаний.</div>';}
function newReminderDraft(r){return r?clone(r):{title:'',kind:'signal',schedule:'weekly',minute:0,time:'15:00',first:day(state.now),days:[1],interval:14,unit:'days',repeat:30,enabled:true};}
function reminderEditor(){const d=state.reminderDraft;return header(state.reminderEdit?'Изменить напоминание':'Новое напоминание','Расписание остаётся под твоим контролем.')+`<form class="nx-form" data-reminder-form>${field('Название','reminderTitle',d.title)}<div class="nx-formrow">${select('Режим','reminderKind',[['signal','Простой сигнал'],['confirmed','Дело с подтверждением']],d.kind)}${select('Повторение','reminderSchedule',[['weekly','По дням недели'],['hourly','Каждый час'],['after','После выполнения']],d.schedule)}</div><div class="nx-settings-section"><h3>Когда напоминать</h3><div class="nx-small nx-muted">Для фиксированного расписания дни и время не сдвигаются после выполнения.</div><div class="nx-formrow">${field('Первое срабатывание, дата','reminderFirst',d.first,'date')}${field('Время','reminderTime',d.time,'time')}</div><div class="nx-rankchoices">${[['1','Пн'],['2','Вт'],['3','Ср'],['4','Чт'],['5','Пт'],['6','Сб'],['0','Вс']].map(([n,label])=>checkbox(label,'weekday-'+n,d.days.includes(Number(n)))).join('')}</div><div class="nx-formrow">${field('Минута каждого часа','reminderMinute',d.minute,'number','min="0" max="59"')}${field('Интервал после выполнения','reminderInterval',d.interval,'number','min="1"')}</div><div class="nx-formrow">${select('Единица интервала','reminderUnit',[['days','Дни'],['hours','Часы']],d.unit)}${field('Повторять до выполнения, минут','reminderRepeat',d.repeat,'number','min="1"')}</div></div>${checkbox('Напоминание включено','reminderEnabled',d.enabled)}${state.error?'<p class="nx-error" role="alert">Укажите название и корректные значения расписания. Интервал после выполнения доступен для дела с подтверждением.</p>':''}<div class="nx-actions"><button type="button" class="nx-button nx-primary" data-action="save-reminder">Сохранить напоминание</button><button type="button" class="nx-button" data-action="cancel-reminder">К напоминаниям</button></div></form>`;}
function collectReminder(){const f=main.querySelector('[data-reminder-form]');if(!f)return;const v=n=>f.elements[n].value;Object.assign(state.reminderDraft,{title:v('reminderTitle'),kind:v('reminderKind'),schedule:v('reminderSchedule'),first:v('reminderFirst'),time:v('reminderTime'),minute:Number(v('reminderMinute')),interval:Number(v('reminderInterval')),unit:v('reminderUnit'),repeat:Number(v('reminderRepeat')),days:[0,1,2,3,4,5,6].filter(d=>f.elements['weekday-'+d].checked),enabled:f.elements.reminderEnabled.checked});}
function settingsView(){const s=state.settings;return header('Настройки','Спокойная работа — по твоим правилам.')+`<form data-settings-form><div class="nx-settings-grid"><section class="nx-settings-section"><h3>Уведомления</h3><p class="nx-small nx-muted">Карточки не забирают фокус и остаются до закрытия.</p>${select('Показывать на мониторе','monitor',[['auto','Автоматический выбор'],['primary','Основной монитор'],['secondary','Дополнительный монитор']],s.monitor)}${select('Монитор для полноэкранного режима','secondary',[['Дополнительный монитор','Дополнительный монитор']],s.secondary)}${field('Обычное откладывание, минут','snooze',s.snooze,'number','min="1"')}${checkbox('Короткий негромкий звук','sound',s.sound)}<p class="nx-small nx-muted">До двух карточек. При наведении они не перемещаются. «Ещё 30 минут» вопроса считается по активному времени.</p></section><section class="nx-settings-section"><h3>Периодическая сводка</h3><p class="nx-small nx-muted">Напоминает о незавершённых задачах, даже во время занятия.</p>${checkbox('Показывать сводку','summary',s.summary)}${field('Интервал сводки, минут','summaryMinutes',s.summaryMinutes,'number','min="1"')}${field('Задач в карточке','summaryLimit',s.summaryLimit,'number','min="1" max="10"')}<p class="nx-small nx-muted">Порядок — по срочности. Отложенная задача временно не включается.</p></section></div><section class="nx-settings-section"><h3>Работа в фоне</h3><p class="nx-small nx-muted">Крестик сворачивает приложение в трей. Полный выход — через меню значка.</p>${checkbox('Запускать вместе с Windows','autorun',s.autorun)}<p class="nx-small nx-muted">После сна или перезапуска занятие остаётся на паузе до «Продолжить».</p></section>${state.error?'<p class="nx-error" role="alert">Интервалы должны быть положительными, число задач — от 1 до 10.</p>':''}<div class="nx-actions"><button type="button" class="nx-button nx-primary" data-action="save-settings">Сохранить настройки</button>${settingsSaved?'<span class="nx-small nx-muted">Настройки сохранены</span>':''}</div></form>`;}
extraView=function(){return state.page==='reminders'?reminderList():state.page==='reminder-edit'?reminderEditor():settingsView();};
render=function(){state.filter=currentFilter().status;app.dataset.detail=String(state.detailOnly);renderSidebar();sidebar.querySelectorAll('.nx-navbutton').forEach(b=>b.setAttribute('aria-label',b.textContent.trim()));if(state.page==='reminder-edit')sidebar.querySelector('[data-page="reminders"]')?.setAttribute('aria-current','page');main.innerHTML=(state.page==='month'?monthView():state.page==='new'?editorView():['settings','reminders','reminder-edit'].includes(state.page)?extraView():listView())+`<div class="nx-status" role="status" aria-live="polite">${esc(state.notice)}${removedTask?'<button class="nx-button" data-action="undo-delete">'+icon('undo-2')+'Восстановить удалённое</button>':''}</div><div class="nx-footnote">${icon('hard-drive')}Задачи, планы и заметки в одном месте</div>`;const actions=main.querySelector('.nx-detail .nx-actions');if(actions&&getTask(state.selected))actions.insertAdjacentHTML('beforeend',`<button class="nx-button nx-delete" data-action="delete-task" data-id="${state.selected}">${icon('trash-2')}Удалить</button>`);if(state.page==='new'&&!state.preview)main.querySelector('textarea')?.closest('label').insertAdjacentHTML('beforebegin',`<div class="nx-formatbar" role="group" aria-label="Форматирование"><button class="nx-button" data-action="format-bold">${icon('bold')}Жирный</button><button class="nx-button" data-action="format-italic">${icon('italic')}Курсив</button><span class="nx-small nx-muted">Выделение + * → *текст*</span></div>`);refreshIcons();paintNotification();updateTimerLabels();};
function toastBody(n){const t=getTask(n.taskId),r=getReminder(n.reminderId);const label=n.kind==='checkin'?'ВРЕМЯ ПРОВЕРИТЬ':n.kind==='summary'?'СВОДКА ЗАДАЧ':n.kind==='signal'?'ПРОСТОЙ СИГНАЛ':'НАПОМИНАНИЕ';const title=n.kind==='checkin'?'Сделал задачу?':n.kind==='summary'?'Вернёмся к делам?':t?.title||r?.title||'Напоминание';return `<article class="nx-toast" data-toast="${n.id}"><div class="nx-checkinhead"><span>NOTIFS · ${label}</span><button class="nx-iconbutton" data-action="dismiss-toast" data-toast-id="${n.id}" aria-label="Закрыть уведомление">${icon('x')}</button></div><h3>${esc(title)}</h3>${n.kind==='checkin'?`<p>${esc(t?.title)}</p><p>Активное время — ${unsignedDuration(Math.floor(activeElapsed(state.sessions[n.taskId])/60000))}, без пауз.</p>`:n.kind==='summary'?`<div class="nx-toast-list">${(n.taskIds||[]).map(id=>{const x=getTask(id);return x?`<div>${esc(x.rank)} · ${esc(x.title)}</div>`:'';}).join('')}</div>`:`<p>${t?age(t):r?.kind==='confirmed'?'Дело ждёт отметки выполнения.':'Небольшой перерыв пойдёт на пользу.'}</p>`}<div class="nx-actions">${n.kind==='summary'?'<button class="nx-button nx-primary" data-action="toast-open-list">Открыть задачи</button>':n.kind==='signal'?'':`<button class="nx-button nx-primary" data-action="${r?'reminder-done':'complete'}" data-id="${r?.id??t?.id}">${icon('check')}Готово</button><button class="nx-button" data-action="${n.kind==='checkin'?'extend':'snooze-toast'}" data-id="${t?.id||''}" data-toast-id="${n.id}">${n.kind==='checkin'?'Ещё 30 минут':'Отложить на '+state.settings.snooze+' мин'}</button>`}</div></article>`;}
paintNotification=function(){state.toasts=state.toasts.filter(n=>n.kind==='summary'?((n.taskIds=n.taskIds.filter(id=>{const t=getTask(id);return t&&!t.done&&(!t.snooze||stamp(t.snooze)<=state.now);})).length):n.taskId?!!getTask(n.taskId)&&!getTask(n.taskId).done&&(n.kind!=='checkin'||!!state.sessions[n.taskId]):!!getReminder(n.reminderId));checkin.hidden=!state.toasts.length;if(checkin.hidden)return;checkin.innerHTML=`<div class="nx-hideall"><button data-action="hide-toasts">Скрыть все ${icon('x')}</button></div>`+state.toasts.map(toastBody).join('');refreshIcons();};
checkin.addEventListener('pointerenter',()=>{state.toastHover=true;});
checkin.addEventListener('pointerleave',()=>{state.toastHover=false;if(state.pendingToasts.length){state.toasts=[...state.toasts,...state.pendingToasts].slice(-2);state.pendingToasts=[];paintNotification();}});
updateTime=function(){state.now=initialNow+(Date.now()-realStart)+state.offset;for(const [id,s] of Object.entries(state.sessions)){if(s.due&&state.now>=s.due&&!s.notified&&!getTask(id)?.done){s.notified=true;notify('checkin',Number(id));}}updateTimerLabels();};
function confirm(title,text,action){confirmAction=action;deleteDialog.innerHTML=`<h2 id="nx-delete-title">${esc(title)}</h2><p id="nx-delete-description">${esc(text)}</p><div class="nx-actions"><button class="nx-button" data-action="keep-task" autofocus>Оставить</button><button class="nx-button nx-danger" data-action="confirm-custom">Подтвердить</button></div>`;positionModal(deleteDialog);}
function stashDeletion(kind,item){const s=state.sessions[item.id];removedTask={kind,item:clone(item),draft:clone(state.drafts['task-'+item.id]||null),session:s?{...clone(s),activeMs:activeElapsed(s),activeSince:null,pausedAt:state.now,remainingMs:s.pausedAt?s.remainingMs:s.due===null?null:Math.max(0,s.due-state.now),due:null}:null};if(kind==='task'){state.tasks=state.tasks.filter(t=>t.id!==item.id);delete state.sessions[item.id];delete state.drafts['task-'+item.id];removeToasts(n=>n.taskId===item.id);}else{state.reminders=state.reminders.filter(r=>r.id!==item.id);removeToasts(n=>n.reminderId===item.id);}state.notice='Удалено. Последнее удаление можно восстановить.';}
function restoreDeletion(){const s=removedTask;if(!s)return;if(s.kind==='reminder'){state.reminders.push({...s.item,enabled:false});state.page='reminders';}else{state.tasks.push(s.item);if(s.session)state.sessions[s.item.id]=s.session;if(s.draft)state.drafts['task-'+s.item.id]=s.draft;state.page='tasks';state.selected=s.item.id;}removedTask=null;state.notice='Восстановлено. Занятие или расписание возвращено без автоматического запуска.';}
function completeTask(t){holdOrder=filterItems(baseItems()).map(x=>x.id);t.done=!t.done;t.doneAt=t.done?new Date(state.now).toISOString().slice(0,19):null;state.sticky.add(t.id);if(t.done){t.lastStart=state.sessions[t.id]?.start||t.lastStart;delete state.sessions[t.id];removeToasts(n=>n.taskId===t.id);}state.notice=t.done?'Выполнено. Карточка остаётся в списке.':'Задача возвращена в работу.';}
function reminderDone(r){if(!r||!r.due||stamp(r.due)>state.now)return;r.history.push({due:r.due,completed:new Date(state.now).toISOString().slice(0,19)});r.due=r.schedule==='after'?new Date(state.now+r.interval*(r.unit==='hours'?3600000:dayMs)).toISOString().slice(0,19):null;removeToasts(n=>n.reminderId===r.id);state.notice='Выполнение сохранено. Следующий цикл — по расписанию.';}
function navigate(page){saveDraft();state.sticky.clear();holdOrder=[];state.detailOnly=false;state.error=false;if(page==='new')openTaskEditor();else{state.page=page==='week'?state.calendarPage:page;}state.notice='';}
const customActions=new Set(['nav','select','filter','start','pause','resume','cancel-session','complete','extend','edit','save','source','preview','delete-task','keep-task','confirm-delete','undo-delete','format-bold','format-italic','toggle-reminder','linen','open-filters','close-filters','reset-filters','apply-filters','back-list','discard-draft','new-reminder','open-reminder','cancel-reminder','save-reminder','delete-reminder','reminder-done','save-settings','hide-toasts','dismiss-toast','snooze-toast','toast-open-list','confirm-custom','today']);
root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||!root.contains(b))return;const a=b.dataset.action,t=getTask(b.dataset.id),r=getReminder(b.dataset.id);if(b.dataset.demo){event.preventDefault();event.stopImmediatePropagation();saveDraft();const kind=b.dataset.demo;if(kind==='skip'){state.offset+=30*60000;updateTime();}else if(kind==='advance'){const due=Math.min(...Object.values(state.sessions).filter(s=>s.due&&!s.pausedAt&&!s.notified).map(s=>s.due));if(Number.isFinite(due)){state.offset+=Math.max(0,due-state.now)+1;updateTime();}}else if(kind==='personal')notify('personal',state.tasks.find(t=>!t.done)?.id);else if(kind==='signal')notify('signal',null,101);else if(kind==='summary')notify('summary');else if(kind==='sleep'){pauseEverySession();state.notice='Занятия на паузе. Для продолжения нажмите «Продолжить».';}else if(kind==='restart'){const data=snapshot();loadSnapshot(data);state.page='tasks';state.notice='После перезапуска: черновики и данные сохранены, занятия на паузе, старый стек закрыт.';}else if(kind==='reset'){try{localStorage.removeItem(storeKey);}catch{}location.reload();return;}remember();render();return;}if(!customActions.has(a)){if(a==='month')state.calendarPage='month';if(a==='back-week')state.calendarPage='week';return;}event.preventDefault();event.stopImmediatePropagation();if(state.page==='new'&&!['format-bold','format-italic'].includes(a))saveDraft();state.notice='';
 if(a==='nav')navigate(b.dataset.page);
 else if(a==='select'&&t){state.selected=t.id;state.detailOnly=true;if(dialog.open){dialog.close();state.period={...state.range};state.week=startWeek(state.range.from);state.page='week';state.calendarPage='week';}}
 else if(a==='back-list')state.detailOnly=false;
 else if(a==='filter'){currentFilter().status=b.dataset.filter;state.sticky.clear();holdOrder=[];}
 else if(a==='open-filters'){filterDraft=clone(currentFilter());filterDialog.innerHTML=filterForm();positionModal(filterDialog);return;}
 else if(a==='close-filters'){filterDialog.close();return;}
 else if(a==='reset-filters'){filterDraft={...cleanFilter(),status:pageKey()==='history'?'done':'all'};filterDialog.innerHTML=filterForm();refreshIcons();return;}
 else if(a==='apply-filters'){const f=collectFilter(),invalid=(f.min!==''&&Number(f.min)<=0)||(f.max!==''&&Number(f.max)<=0)||(f.min!==''&&f.max!==''&&Number(f.min)>Number(f.max))||(f.deadlineFrom&&f.deadlineTo&&f.deadlineFrom>f.deadlineTo)||(f.createdFrom&&f.createdTo&&f.createdFrom>f.createdTo);if(invalid){filterDialog.querySelector('[data-filter-error]').textContent='Начало диапазона не может быть позже конца. Оценка должна быть положительной.';return;}state.prefs[pageKey()]=f;state.sticky.clear();holdOrder=[];filterDialog.close();}
 else if(a==='start'&&t){pauseEverySession(t.id);state.sessions[t.id]={start:state.now,activeSince:state.now,activeMs:0,pausedAt:null,remainingMs:null,due:t.estimate?state.now+t.estimate*60000:null,notified:false};t.lastStart=state.now;state.notice='Начало занятия отмечено. Обычные напоминания продолжаются.';}
 else if(a==='pause'&&t)pauseSession(t.id);
 else if(a==='resume'&&t)resumeSession(t);
 else if(a==='cancel-session'&&t){delete state.sessions[t.id];delete t.lastStart;removeToasts(n=>n.kind==='checkin'&&n.taskId===t.id);state.page='tasks';state.selected=t.id;}
 else if(a==='complete'&&t)completeTask(t);
 else if(a==='extend'&&t){const s=state.sessions[t.id];if(s){s.remainingMs=30*60000;s.due=s.pausedAt?null:state.now+s.remainingMs;s.notified=false;removeToasts(n=>n.kind==='checkin'&&n.taskId===t.id);state.notice='Следующий вопрос — через 30 активных минут.';}}
 else if(a==='edit'&&t)openTaskEditor(t);
 else if(a==='save'){saveTask();return;}
 else if(a==='discard-draft'){delete state.drafts[draftKey()];const current=getTask(state.edit);openTaskEditor(current);state.notice='Текущий черновик отброшен.';}
 else if(a==='source')state.preview=false;
 else if(a==='preview')state.preview=true;
 else if(a==='format-bold'||a==='format-italic'){formatSelection(a==='format-bold'?'**':'*',true);remember();return;}
 else if(a==='delete-task'&&t){confirm('Удалить задачу?','«'+t.title+'» исчезнет из списка и календаря. Последнее удаление можно восстановить.',()=>stashDeletion('task',t));return;}
 else if(a==='keep-task'){deleteDialog.close();confirmAction=null;return;}
 else if(a==='confirm-custom'){deleteDialog.close();confirmAction?.();confirmAction=null;}
 else if(a==='undo-delete')restoreDeletion();
 else if(a==='today'){state.week=startWeek(day(state.now));state.period={from:day(state.now),to:day(state.now)};state.range={...state.period};state.page='week';state.calendarPage='week';}
 else if(a==='new-reminder'){state.reminderEdit=null;state.reminderDraft=newReminderDraft();state.page='reminder-edit';state.error=false;}
 else if(a==='open-reminder'&&r){dialog.close();state.reminderEdit=r.id;state.reminderDraft=newReminderDraft(r);state.page='reminder-edit';state.error=false;}
 else if(a==='cancel-reminder'){state.page='reminders';state.error=false;}
 else if(a==='save-reminder'){collectReminder();const d=state.reminderDraft,original=getReminder(state.reminderEdit);if(!d.title.trim()||!d.first||!d.time||d.minute<0||d.minute>59||d.interval<=0||d.repeat<=0||(d.schedule==='weekly'&&!d.days.length)||(d.schedule==='after'&&d.kind==='signal')){state.error=true;render();return;}const commit=()=>{const item={...d,id:original?.id??Math.max(100,...state.reminders.map(x=>x.id))+1,history:original?.history||[],due:d.kind==='confirmed'?(original?.due||d.first+'T'+d.time+':00'):null};if(original)Object.assign(original,item);else state.reminders.push(item);if(d.kind==='signal')removeToasts(n=>n.reminderId===item.id&&n.kind!=='signal');state.page='reminders';state.error=false;state.notice='Напоминание сохранено.';};if(original?.due&&original.kind==='confirmed'&&d.kind==='signal'){confirm('Снять текущее дело?','Переход к простому сигналу снимет невыполненное дело. Существующие факты выполнения сохранятся.',commit);return;}commit();}
 else if(a==='delete-reminder'&&r){confirm('Удалить напоминание?','«'+r.title+'»: расписание, текущее дело и история выполнений исчезнут из календаря. Последнее удаление можно восстановить.',()=>stashDeletion('reminder',r));return;}
 else if(a==='toggle-reminder'&&r){r.enabled=!r.enabled;if(!r.enabled)removeToasts(n=>n.reminderId===r.id);else if(r.kind==='confirmed'&&r.due&&stamp(r.due)<=state.now)notify('reminder',null,r.id);}
 else if(a==='reminder-done'&&r)reminderDone(r);
 else if(a==='save-settings'){const f=main.querySelector('[data-settings-form]'),d={...state.settings};for(const name of Object.keys(d)){const el=f.elements[name];if(el)d[name]=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;}if(d.snooze<=0||d.summaryMinutes<=0||d.summaryLimit<1||d.summaryLimit>10){state.error=true;render();return;}state.settings=d;state.error=false;settingsSaved='saved';state.notice='Настройки сохранены.';}
 else if(a==='hide-toasts'){state.toasts=[];state.pendingToasts=[];paintNotification();remember();return;}
 else if(a==='dismiss-toast'){removeToasts(n=>n.id===Number(b.dataset.toastId));paintNotification();remember();return;}
 else if(a==='toast-open-list'){navigate('tasks');removeToasts(n=>n.kind==='summary');}
 else if(a==='snooze-toast'){const n=state.toasts.find(x=>x.id===Number(b.dataset.toastId));if(n){const until=new Date(state.now+state.settings.snooze*60000).toISOString().slice(0,19),item=n.taskId?getTask(n.taskId):getReminder(n.reminderId);item.snooze=until;removeToasts(x=>x.kind!=='checkin'&&(n.taskId?x.taskId===n.taskId:x.reminderId===n.reminderId));}}
 remember();render();if(dialog.open)renderDialog();if(state.page==='new'&&(a==='edit'||a==='nav'))main.querySelector('[name="title"]')?.focus({preventScroll:true});
},true);
root.addEventListener('input',()=>{if(state.page==='new'){saveDraft();remember();}if(state.page==='reminder-edit')collectReminder();});
root.addEventListener('keydown',event=>{const f=event.target.closest('textarea[name="description"]');if(!f||event.isComposing)return;const star=!event.ctrlKey&&!event.metaKey&&!event.altKey&&(event.key==='*'||(event.shiftKey&&event.code==='Digit8')),shortcut=(event.ctrlKey||event.metaKey)&&!event.altKey&&['b','i'].includes(event.key.toLowerCase());if(shortcut||(star&&f.selectionStart!==f.selectionEnd)){event.preventDefault();event.stopImmediatePropagation();if(!event.repeat)formatSelection(shortcut&&event.key.toLowerCase()==='b'?'**':'*',shortcut);remember();}},true);
filterDialog.addEventListener('cancel',()=>{filterDraft=null;});
root.addEventListener('click',()=>{queueMicrotask(()=>{if(['week','month'].includes(state.page)){state.calendarPage=state.page;remember();}});});

// Reveal only controls belonging to the chosen schedule; irrelevant values stay in the draft.
reminderEditor=function(){
 const d=state.reminderDraft;
 const when=d.schedule==='weekly'?`<div class="nx-rankchoices">${[['1','Пн'],['2','Вт'],['3','Ср'],['4','Чт'],['5','Пт'],['6','Сб'],['0','Вс']].map(([n,label])=>checkbox(label,'weekday-'+n,d.days.includes(Number(n)))).join('')}</div>`:d.schedule==='hourly'?field('Минута каждого часа','reminderMinute',d.minute,'number','min="0" max="59"'):`<div class="nx-formrow">${field('Через сколько после выполнения','reminderInterval',d.interval,'number','min="1"')}${select('Единица интервала','reminderUnit',[['days','Дни'],['hours','Часы']],d.unit)}</div>`;
 return header(state.reminderEdit?'Изменить напоминание':'Новое напоминание','Расписание остаётся под твоим контролем.')+`<form class="nx-form" data-reminder-form>${field('Название','reminderTitle',d.title)}<div class="nx-formrow">${select('Режим','reminderKind',[['signal','Простой сигнал'],['confirmed','Дело с подтверждением']],d.kind)}${select('Повторение','reminderSchedule',[['weekly','По дням недели'],['hourly','Каждый час'],...(d.kind==='confirmed'?[['after','После выполнения']]:[])],d.schedule)}</div><section class="nx-settings-section"><h3>Когда напоминать</h3><p class="nx-small nx-muted">${d.schedule==='after'?'Следующий срок отсчитывается от фактического выполнения.':'Фиксированное расписание не сдвигается после выполнения.'}</p><div class="nx-formrow">${field('Первое срабатывание, дата','reminderFirst',d.first,'date')}${field('Время','reminderTime',d.time,'time')}</div>${when}${d.kind==='confirmed'?field('Повторять до выполнения, минут','reminderRepeat',d.repeat,'number','min="1"'):''}</section>${checkbox('Напоминание включено','reminderEnabled',d.enabled)}${state.error?'<p class="nx-error" role="alert">Укажите название и корректные значения расписания.</p>':''}<div class="nx-actions"><button type="button" class="nx-button nx-primary" data-action="save-reminder">Сохранить напоминание</button><button type="button" class="nx-button" data-action="cancel-reminder">К напоминаниям</button></div></form>`;
};
collectReminder=function(){const f=main.querySelector('[data-reminder-form]');if(!f)return;const d=state.reminderDraft,v=(name,fallback)=>f.elements[name]?.value??fallback;Object.assign(d,{title:v('reminderTitle',d.title),kind:v('reminderKind',d.kind),schedule:v('reminderSchedule',d.schedule),first:v('reminderFirst',d.first),time:v('reminderTime',d.time),minute:Number(v('reminderMinute',d.minute)),interval:Number(v('reminderInterval',d.interval)),unit:v('reminderUnit',d.unit),repeat:Number(v('reminderRepeat',d.repeat)),enabled:f.elements.reminderEnabled.checked});if(f.elements['weekday-0'])d.days=[0,1,2,3,4,5,6].filter(n=>f.elements['weekday-'+n].checked);};
root.addEventListener('change',event=>{if(state.page==='reminder-edit'&&['reminderKind','reminderSchedule'].includes(event.target.name)){collectReminder();if(state.reminderDraft.kind==='signal'&&state.reminderDraft.schedule==='after')state.reminderDraft.schedule='weekly';render();main.querySelector(`[name="${event.target.name}"]`)?.focus({preventScroll:true});}if(filterDialog.open)updateFilterControls();});
function updateFilterControls(){const form=filterDialog.querySelector('form');if(!form)return;const f=form.elements;for(const name of ['min','max'])f[name].disabled=f.estimateMode.value!=='range';for(const name of ['deadlineFrom','deadlineTo'])f[name].disabled=f.deadlineMode.value!=='range';const labels={rank:['Важные сначала · S → D','Менее важные · D → S'],estimate:['Короткие сначала','Длинные сначала'],deadline:['Ближайшие сначала','Поздние сначала'],created:['Сначала старые','Сначала новые'],urgency:['Автоматически','Автоматически']};const dir=f.direction.value;f.direction.innerHTML=labels[f.sort.value].map((text,i)=>option(i?'desc':'asc',text,dir)).join('');f.direction.disabled=f.sort.value==='urgency';}
const originalFilterForm=filterForm;
filterForm=function(){const html=originalFilterForm();queueMicrotask(updateFilterControls);return html;};
const renderProduct=render;
render=function(){if(['week','month'].includes(state.page))state.calendarPage=state.page;renderProduct();if(state.page==='settings'){const el=main.querySelector('[name="secondary"]');if(el){const label=el.parentElement;el.remove();label.insertAdjacentHTML('beforeend','<span class="nx-small nx-muted">Дополнительный монитор · из подключённых экранов</span>');}}};
const updateProductTimers=updateTimerLabels;
updateTimerLabels=function(){updateProductTimers();root.querySelector('[data-demo="advance"]').disabled=!Object.values(state.sessions).some(s=>s.due&&!s.pausedAt&&!s.notified);};
const sessionStatus=sessionText;
sessionText=function(id){const s=state.sessions[id];return s?.notified?(s.pausedAt?'На паузе · вопрос уже показан':'Оценка прошла · вопрос уже показан'):sessionStatus(id);};
// Browsers may merge consecutive execCommand edits. Keep each formatting command undoable alone.
let formatRedo=[];
const applyFormatCommand=formatSelection;
formatSelection=function(marker,toggle=false){const f=main.querySelector('textarea[name="description"]');if(!f)return;const before={value:f.value,start:f.selectionStart,end:f.selectionEnd};applyFormatCommand(marker,toggle);const entry=formatHistory.at(-1);Object.assign(entry,before,{after:f.value,afterStart:f.selectionStart,afterEnd:f.selectionEnd});formatRedo=[];};
root.addEventListener('keydown',event=>{const f=event.target.closest('textarea[name="description"]');if(!f||!(event.ctrlKey||event.metaKey)||event.altKey)return;const redo=event.key.toLowerCase()==='y'||(event.key.toLowerCase()==='z'&&event.shiftKey),undo=event.key.toLowerCase()==='z'&&!event.shiftKey;if(!redo&&!undo)return;const entry=(redo?formatRedo:formatHistory).at(-1);if(!entry||f.value!==(redo?entry.value:entry.after))return;event.preventDefault();event.stopImmediatePropagation();(redo?formatRedo:formatHistory).pop();(redo?formatHistory:formatRedo).push(entry);f.value=redo?entry.after:entry.value;f.setSelectionRange(redo?entry.afterStart:entry.start,redo?entry.afterEnd:entry.end);f.dispatchEvent(new Event('input',{bubbles:true}));},true);
globalThis.addEventListener('openai:set_globals',event=>{const saved=event.detail?.globals?.widgetState?.privateContent||event.detail?.globals?.widgetState;if(saved?.notifs&&saved.revision!==hostRevision){hostRevision=saved.revision||'';loadSnapshot(saved.notifs);render();}});
const paintStack=paintNotification;
paintNotification=function(){const positions=new Map([...checkin.querySelectorAll('[data-toast]')].map(el=>[el.dataset.toast,el.getBoundingClientRect().top]));paintStack();for(const el of checkin.querySelectorAll('[data-toast]')){if(!positions.has(el.dataset.toast))continue;el.style.animation='none';const shift=positions.get(el.dataset.toast)-el.getBoundingClientRect().top;if(shift&&!matchMedia('(prefers-reduced-motion:reduce)').matches)el.animate([{transform:`translateY(${shift}px)`},{transform:'translateY(0)'}],{duration:180,easing:'ease-out'});}};
